PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?e ?name WHERE {
  ?e a ?cls .
  OPTIONAL { ?e skos:prefLabel ?name }
  FILTER(str(?e) != str(?cls))
}

PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ref: <http://w3-id.org/2019/ref#>
SELECT ?e ?rdfs ?cls ?tsid ?point_uri
WHERE {
  OPTIONAL { ?x ref:hasTimeseriesId ?tsid . ?ts ?point_uri . ?ts rdfs:subject ?x . FILTER(str(?x) LIKE "%Chiller%" || str(?x) LIKE "%CHWPump02%" || str(?x) LIKE "%SupplyFan_AHU01%")) }
  FILTER(str(?e) != str(?cls))
  ?e a ?cls .
}
LIMIT 200

SELECT ?s WHERE {
  ?s rdf:type ?t .
  FILTER(str(?s) LIKE "%Chiller%")
}
LIMIT 50

